const keys = ['vance', 'okafor', 'castellane', 'aldaine', 'vale'];
const rows = $input.all().map(i => i.json).filter(r => r.note && keys.includes(r.agent));
const notes = {};
for (const k of keys) {
  const mine = rows.filter(r => r.agent === k).slice(-3).map(r => '- ' + r.note);
  notes[k] = mine.length ? mine.join(String.fromCharCode(10)) : 'none yet';
}
return [{ json: { notes } }];

