const brief = $('Run Inputs').first().json.brief;
const text = String($input.first().json.text || '');
const m = text.match(/BUILD:[ *]*(yes|no)/i);
const guessed = /(build|code|develop|prototype|website|web app|app)/i.test(brief);
const build = m ? m[1].toLowerCase() === 'yes' : guessed;
const frame = text ? text.replace(/[*_ ]*memory:[\s\S]*$/i, '').trim() : 'The director could not frame this brief. Work from the brief itself and state your assumptions.';
return [{ json: { frame, build, frame_ok: !!text } }];

