const brief = $('Run Inputs').first().json.brief.slice(0, 80);
function safeText(name) {
  try { return String($(name).first().json.text || ''); } catch (e) { return ''; }
}
function lesson(t) {
  const m = [...t.matchAll(/memory:/gi)].pop();
  if (!m) { return ''; }
  return t.slice(m.index + 7).replace(/[*_]/g, '').trim().split('\n')[0].slice(0, 200);
}
const sources = [['vance', 'Vance: Final Review'], ['okafor', 'Okafor: Research'], ['castellane', 'Castellane: Prioritise'], ['aldaine', 'Aldaine: Design'], ['vale', 'Vale: Build']];
const rows = sources.map(([agent, name]) => ({ agent, project: brief, note: lesson(safeText(name)) })).filter(r => r.note);
if (rows.length === 0) { return [{ json: { agent: 'none', project: brief, note: '' } }]; }
return rows.map(r => ({ json: r }));

const cfg = $('Run Inputs').first().json;
const plan = $('Read The Plan').first().json;
function get(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
function body(j) { return String(j.text || '').replace(/[*_ ]*memory:[\s\S]*$/i, '').trim(); }
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
const team = [
  { node: 'Okafor: Research', who: 'Prof. Anselm Okafor', role: 'Director of Research', needed: true },
  { node: 'Castellane: Prioritise', who: 'Mira Castellane', role: 'Chief Product Strategist', needed: true },
  { node: 'Aldaine: Design', who: 'Kenji Aldaine', role: 'Design Director', needed: true },
  { node: 'Vale: Build', who: 'Soren Vale', role: 'Distinguished Engineer', needed: plan.build },
];
const review = get('Vance: Final Review');
const warnings = [];
function reason(j) { const e = String(j.error?.message || j.error || ''); return e ? ' Reason: ' + e.slice(0, 140) : ''; }
if (!plan.frame_ok) { warnings.push('Dr. Vance could not frame the brief, so the team worked from the brief alone.' + reason(get('Vance: Frame The Brief'))); }
if (!body(review)) { warnings.push('Dr. Vance could not write the final review. Read the sections below directly.' + reason(review)); }
let tokens = (get('Vance: Frame The Brief').usage?.totalTokens || 0) + (review.usage?.totalTokens || 0);
const sections = team.filter(t => t.needed).map(t => {
  const j = get(t.node);
  tokens += j.usage?.totalTokens || 0;
  const text = body(j);
  if (!text) { warnings.push(t.who + ' could not finish.' + reason(j)); }
  return { who: t.who, role: t.role, text };
});
const research = get('Okafor: Research');
const papers = [];
const updates = [];
for (const t of team.concat([{ node: 'Vance: Final Review', who: 'Dr. Imara Vance' }])) {
  let used = false;
  for (const call of get(t.node).toolCalls || []) {
    for (const v of Object.values(call.result?.data || {})) {
      const first = Array.isArray(v) ? v[0] : null;
      const res = first?.json || first || {};
      for (const p of (res.results || [])) { if (!papers.some(x => x.title === p.title)) { papers.push(p); } }
      if (res.checked_on) {
        used = true;
        for (const n of (res.news || []).concat(res.papers || [])) {
          if (n.title && !updates.some(u => u.title === n.title)) { updates.push({ date: n.date, title: n.title, source: n.doi ? 'paper' : 'headline', seen_by: t.who }); }
        }
      }
    }
  }
  if (t.needed !== false && !used && body(get(t.node))) { warnings.push(t.who + ' did not check for recent updates in this run.'); }
}
const researchText = body(research);
if (researchText && papers.length === 0) { warnings.push('Prof. Okafor found no papers through the search tool, so treat the research section as unsourced.'); }
const unmatched = [];
for (const m of researchText.matchAll(/\(([^()]*?(?:19|20)[0-9]{2})\)/g)) {
  const cited = m[1].toLowerCase();
  const surname = cited.trim().split(/[\s,]/)[0];
  const titleBit = cited.replace(/,? *(?:19|20)[0-9]{2}$/, '').trim();
  const known = papers.some(p => String(p.authors).toLowerCase().includes(surname) || String(p.title).toLowerCase().includes(titleBit) || updates.some(u => u.title.toLowerCase().includes(titleBit)));
  if (surname && !/^[0-9]/.test(surname) && !known) { unmatched.push(m[1]); }
}
if (unmatched.length) { warnings.push('These citations do not match any paper the search returned, so ignore them: ' + [...new Set(unmatched)].join('; ')); }
function lum(hex) {
  const v = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255).map(c => c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
  return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2];
}
const designText = body(get('Aldaine: Design'));
const hexes = [...new Set((designText.match(/#[0-9a-fA-F]{6}(?![0-9a-fA-F])/g) || []).map(h => h.toLowerCase()))];
const contrast = [];
for (let i = 0; i < hexes.length; i++) {
  for (let j = i + 1; j < hexes.length; j++) {
    const a = lum(hexes[i]); const b = lum(hexes[j]);
    contrast.push({ pair: hexes[i] + ' on ' + hexes[j], ratio: Math.round(((Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05)) * 10) / 10 });
  }
}
function card(title, sub, text) {
  return '<div style="background:#fff;color:#1a1a1a;border:1px solid #ccc;border-radius:8px;padding:14px;margin:14px 0"><h2 style="margin:0;font-size:18px">' + esc(title) + '</h2><p style="margin:0 0 8px;color:#555"><small>' + esc(sub) + '</small></p><div style="white-space:pre-wrap;overflow-wrap:anywhere">' + esc(text || 'Not completed.') + '</div></div>';
}
const sourceList = papers.map(p => '<li>' + esc(p.title) + ' (' + esc(p.year) + ')' + (p.doi ? ', doi:' + esc(p.doi) : ', no DOI listed') + '</li>').join('');
const sourceHtml = papers.length ? '<div style="background:#fff;color:#1a1a1a;border:1px solid #ccc;border-radius:8px;padding:14px;margin:14px 0"><h2 style="margin:0 0 6px;font-size:18px">Sources returned by the search tool</h2><p style="margin:0 0 6px;color:#555"><small>Listed by code from OpenAlex, not written by an agent. Abstracts only.</small></p><ul style="margin:0;padding-left:20px">' + sourceList + '</ul></div>' : '';
const updateList = updates.slice(0, 12).map(u => '<li>' + esc(u.date) + ' (' + esc(u.source) + '): ' + esc(u.title) + '</li>').join('');
const updateHtml = updates.length ? '<details style="margin:14px 0"><summary>Live updates the team checked in this run</summary><ul>' + updateList + '</ul></details>' : '';
const contrastRows = contrast.map(c => '<li>' + esc(c.pair) + ': ' + c.ratio + ':1 ' + (c.ratio >= 4.5 ? '(passes AA for normal text)' : c.ratio >= 3 ? '(large text only)' : '(fails AA)') + '</li>').join('');
const contrastHtml = contrast.length ? '<details style="margin:14px 0"><summary>Measured contrast of every colour pair in the design</summary><ul>' + contrastRows + '</ul></details>' : '';
const cards = [card('Dr. Imara Vance', 'Studio Director: final review', body(review))].concat(sections.map(s => card(s.who, s.role, s.text))).join('');
const warnHtml = warnings.length ? '<div style="background:#fff4e0;color:#5c3a00;border-radius:8px;padding:10px 14px;margin:14px 0"><b>Please note</b><ul style="margin:6px 0">' + warnings.map(w => '<li>' + esc(w) + '</li>').join('') + '</ul></div>' : '';
const devLine = plan.build ? 'Soren Vale was woken because the brief asks for a build.' : 'Soren Vale stayed on standby because the brief does not ask for a build.';
const report_html = '<div style="max-width:800px;margin:0 auto;text-align:left;font-family:system-ui,sans-serif;line-height:1.5"><h1 style="font-size:22px;margin:0 0 6px">Design Team report</h1><p style="margin:0 0 6px">' + esc(cfg.brief) + '</p><p style="margin:0"><small>' + esc(devLine) + ' The team members are fictional AI characters. Research plans are proposals: no real people were interviewed. Check everything before you use it.</small></p>' + warnHtml + cards + sourceHtml + updateHtml + contrastHtml + '</div>';
return [{ json: { brief: cfg.brief, build: plan.build, frame: plan.frame, warnings, tokens, sections, papers, updates, unmatched_citations: unmatched, contrast, review: body(review), report_html } }];
